def load_config(env):
    port = int(env.get('APP_PORT', 8000))
    if not 1 <= port <= 65535:
        raise ValueError('Invalid port')
    raw = env.get('APP_DEBUG', 'false').strip().lower()
    if raw not in {'true', '1', 'yes', 'false', '0', 'no'}:
        raise ValueError('Invalid boolean')
    return {'host': env.get('APP_HOST', 'localhost'), 'port': port,
            'debug': raw in {'true', '1', 'yes'}}

