import csv
import io
from decimal import Decimal, InvalidOperation

def read_rows(text):
    reader = csv.DictReader(io.StringIO(text))
    if not {'customer', 'amount', 'status'} <= set(reader.fieldnames or []):
        raise ValueError('Missing headers')
    result = []
    for row in reader:
        if any(row.get(k) is None for k in ('customer','amount','status')):
            raise ValueError('Missing field')
        name = row['customer'].strip()
        try:
            amount = Decimal(row['amount'].strip())
        except InvalidOperation as exc:
            raise ValueError('Invalid amount') from exc
        if not name or not amount.is_finite():
            raise ValueError('Invalid row')
        result.append({'customer':name, 'amount':amount,
                       'status':row['status'].strip().lower()})
    return result

