from decimal import Decimal, ROUND_HALF_UP
from .reader import read_rows

def totals(text):
    result = {}
    for row in read_rows(text):
        if row['status'] == 'cancelled':
            continue
        name = row['customer']
        result[name] = result.get(name, Decimal(0)) + row['amount']
    return {name: format(result[name].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')
            for name in sorted(result)}

