def page(items, number, size):
    if type(number) is not int or type(size) is not int or number < 1 or not 1 <= size <= 100:
        raise ValueError('Invalid page parameters')
    rows = sorted(items, key=lambda row: (row['name'].casefold(), row['id']))
    start = (number - 1) * size
    return {'items':rows[start:start+size], 'total':len(rows), 'page':number,
            'pages':(len(rows) + size - 1) // size}

