from .paths import normalize

def load(text):
    result = []
    seen = set()
    for number,line in enumerate(text.splitlines(),1):
        value = line.strip()
        if not value or value.startswith('#'):
            continue
        try:
            name = normalize(value)
        except ValueError as exc:
            raise ValueError(f'line {number}: invalid path') from exc
        if name not in seen:
            seen.add(name)
            result.append(name)
    return result

