import math

def delay(headers, retry_index):
    value = next((v for k,v in headers.items() if k.lower() == 'retry-after'), None)
    try:
        seconds = float(value)
    except (ValueError,TypeError):
        return 2 ** retry_index
    return seconds if math.isfinite(seconds) and seconds >= 0 else 2 ** retry_index

